import heapq


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        domains.append([None] + versions)

    best_vector = None
    best = None
    for values in product(*domains):
        chosen = {name: version for name, version in zip(names, values)
                  if version is not None}
        if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue

        rows = {name: next(row for row in packages[name]
                           if row["version"] == version)
                for name, version in chosen.items()}
        edges = {}
        valid = True
        for name, row in rows.items():
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in deps:
                other = dep["name"]
                if other not in chosen or not dep["min"] <= chosen[other] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(chosen):
            continue

        finished, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in chosen):
            continue

        vector = tuple(chosen.get(name, -1) for name in names)
        if best_vector is None or (vector > best_vector if preference == "maximum"
                                   else vector < best_vector):
            best_vector, best = vector, chosen
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _build_component_01():
    return lambda data: _dependency_solver(data, "maximum", "ascending")


