def _build_component_06():
    def round_value(numerator, mode):
        if mode == "floor":
            return numerator // 10000
        return (numerator + 5000) // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = round_value(raw * (10000 - discount), mode)
            tax = round_value(net * event.get("tax_bp", 0), mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def feasible(selected, data):
        ids = {job["id"] for job in selected}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        for group, (low, high) in data.get("quotas", {}).items():
            if not low <= counts.get(group, 0) <= high:
                return False
        active = []
        for job in sorted(selected, key=lambda j: (j["start"], j["end"], j["id"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                return False
        return True

    def solve(data):
        options = [job for job in data["jobs"]
                   if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        if k > len(options):
            return {"error": "impossible"}
        best_value = None
        best_ids = None
        for selected in combinations(options, k):
            if not feasible(selected, data):
                continue
            ids = tuple(sorted(job["id"] for job in selected))
            value = sum(job["value"] for job in selected)
            if (best_value is None or value > best_value
                    or (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        start = data["start"]
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    choices.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                    remaining - 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for duration, next_remaining in choices:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"], next_mask,
                                               next_remaining))
        return {"arrival": None}
    return solve


